def verifier(assign):
    # Validate presence of necessary fields
    req = ['alpha','t1','u1','v1','t2','u2','v2','t3','u3','v3','delta','gamma','d']
    for k in req:
        if k not in assign:
            # Missing field
            return (False, None)
    alpha = assign['alpha']
    t1 = assign['t1']; u1 = assign['u1']; v1 = assign['v1']
    t2 = assign['t2']; u2 = assign['u2']; v2 = assign['v2']
    t3 = assign['t3']; u3 = assign['u3']; v3 = assign['v3']
    delta = assign['delta']; gamma = assign['gamma']; d = assign['d']
    # Basic domain checks
    if not (isinstance(alpha, int) and alpha >= 3):
        return (False, None)
    for x in [t1,t2,t3,u1,u2,u3,v1,v2,v3,delta,gamma,d]:
        if not isinstance(x, int):
            return (False, None)
    if t1 <= 0 or t2 <= 0 or t3 <= 0:
        return (False, None)
    if u1 != t1 + 1 or v1 != 2*t1:
        return (False, None)
    if u2 != t2 + 1 or v2 != 2*t2:
        return (False, None)
    if u3 != t3 + 1 or v3 != 2*t3:
        return (False, None)
    if d < 3:
        return (False, None)
    # Compute s from (1): the telescoping identity yields sum factor ratio 3*t + 1 when u=t+1, v=2t
    s = 3*t1 + 1  # sum x_n
    # Check that (2) is consistent: the designed ratio equals 3*t2 + 1 = s^2, forcing S2 = s^2 - delta
    if 3*t2 + 1 != s*s:
        return (False, None)
    # Check that (3) is consistent: 3*t3 + 1 must equal 2*s^3 - 3*s*delta - gamma
    if 3*t3 + 1 != 2*(s**3) - 3*s*delta - gamma:
        return (False, None)
    # Ensure discriminant for two-point configuration is positive: s^2 - 2*delta > 0
    if s*s - 2*delta <= 0:
        return (False, None)
    # The minimal configuration occurs with exactly two nonzero x's, say x,y >= 0
    # With S1 = s, S2 = s^2 - delta, we have xy = p = delta/2
    p = Fraction(delta, 2)
    # Use Newton's recurrence for two variables: S_k = s*S_{k-1} - p*S_{k-2}, with S_0 = 2, S_1 = s
    S_prev2 = Fraction(2,1)  # S_0
    S_prev1 = Fraction(s,1)  # S_1
    target_k = 2*d
    if target_k == 0:
        S_target = S_prev2
    elif target_k == 1:
        S_target = S_prev1
    else:
        S_target = None
        for k in range(2, target_k+1):
            S_k = Fraction(s,1)*S_prev1 - p*S_prev2
            S_prev2, S_prev1 = S_prev1, S_k
        S_target = S_k
    # Return exact rational in simplest form
    num = S_target.numerator
    den = S_target.denominator
    ans = str(num) if den == 1 else f"{num}/{den}"
    return (True, ans)


        def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
            """Return dict with assignment/question/answer or raise RuntimeError."""
            start = time.time()
            attempts = 0
            while time.time() - start < timeout_seconds:
                attempts += 1
                rng = _RNGShim(seed + attempts)
                assignment = generator(rng)
                valid, answer = verifier(assignment)
                if valid:
                    question = LANGUAGE_WRAPPER.format(**assignment)
                    return {
                        "assignment": assignment,
                        "question": question,
                        "answer": answer,
                        "attempts": attempts,
                        "elapsed_seconds": time.time() - start,
                    }
            raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

